if DisasterZoneBoot and DisasterZoneBoot.Run("Data/Raids.lua", ...) then return end -- DisasterZone Data/Raids.lua
-- Raid meta table (short names, planner keys, art, map ids): one home for raid information. WoW Forever's raids.
local addonName, ns = ...

-- Keyed by the item data's raid key (Data/Items.lua ns.Data.Raids[i].key, generated by gen_forever_data.py). Read it
-- through ns.ItemDB (GetRaidByInstance, GetRaidByPlanKey, PlanKeyOf, ItemKeyOf, RaidShort, RaidArt).
--   short       the short name the UI shows
--   planKey     the raid planner's key (Data/ForeverRaids.lua): saved raids and the sync use it; never renamed
--   instanceID  the instance map id (GetInstanceInfo's 8th value); nil until `/dz raiddata` has seen the raid
--   art         a loading screen (2048 x 2048 shown at 4:3): { fdid, l, r, t, b }, cx, cy = a card's centre. The new
--               raids have no known loading screen yet: Hyjal Summit borrows the old Hyjal battle's, Barrow Deeps the
--               generic one (Eastern Kingdoms, 131839; was Outland's 131860), Onyxia the Kalimdor one.
--   artTop      where the picture starts under the logo band (a share of the height)
--   mapNames    the names the client may give the raid's map (lower case, found as a part of the name)
--   icon        the raid's LFG icon (My BiS's source rows)
ns.Data = ns.Data or {}

local ART_TOP = 0.29
local ICON = "Interface\\LFGFrame\\LFGIcon-Raid"

local function Art(fdid, cx, cy)
    return { fdid, 0, 1, ART_TOP, 1, cx = cx, cy = cy }
end

ns.Data.RaidMeta = {
    BarrowDeeps = { icon = ICON, short = "Barrow", planKey = "barrow", art = Art(131839, 0.50, 0.45), artTop = ART_TOP,
                    mapNames = { "barrow deeps" } },
    HyjalForever = { icon = ICON, short = "Hyjal", planKey = "hyjal", art = Art(131847, 0.40, 0.45), artTop = ART_TOP,
                     mapNames = { "hyjal summit" } },
    Onyxia = { icon = ICON, short = "Ony", planKey = "ony", instanceID = 249, art = Art(131848, 0.50, 0.45),
               artTop = ART_TOP, mapNames = { "onyxia" } },
}

-- Anything else (the raid planner's "other", an unknown key): no short name, a generic loading screen (the
-- Eastern Kingdoms).
ns.Data.RaidMetaOther = { planKey = "other", art = Art(131839, 0.50, 0.45), artTop = ART_TOP }
